import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

const useMessages = () => {
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Récupérer et nettoyer le token
  const getToken = useCallback(() => {
    try {
      let token = localStorage.getItem('authToken') || 
                  localStorage.getItem('token') || 
                  sessionStorage.getItem('authToken');

      if (!token) {
        console.log('❌ Aucun token trouvé dans le stockage');
        return null;
      }

      // Nettoyer le token
      token = token.trim();
      if ((token.startsWith('"') && token.endsWith('"')) || 
          (token.startsWith("'") && token.endsWith("'"))) {
        token = token.slice(1, -1);
      }

      // Vérifier que c'est un JWT valide
      if (!token.includes('.') || token.split('.').length !== 3) {
        console.error('❌ Token JWT invalide:', token.substring(0, 20) + '...');
        return null;
      }

      return token;
    } catch (error) {
      console.error('❌ Erreur lors de la récupération du token:', error);
      return null;
    }
  }, []);

  // Créer instance axios avec gestion d'erreur améliorée
  const createAxiosInstance = useCallback(() => {
    const token = getToken();

    if (!token) {
      console.error('❌ Impossible de créer l\'instance axios: token manquant');
      throw new Error('Token d\'authentification manquant');
    }

    console.log('🔑 Création instance axios avec token:', token.substring(0, 20) + '...');

    const instance = axios.create({
      baseURL: API_URL,
      timeout: 15000,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    // Intercepteur de réponse
    instance.interceptors.response.use(
      response => {
        console.log(`✅ ${response.config.method?.toUpperCase()} ${response.config.url} - ${response.status}`);
        return response;
      },
      error => {
        const errorData = error.response?.data;
        const status = error.response?.status;

        console.error(`❌ Erreur API ${status}:`, {
          url: error.config?.url,
          method: error.config?.method,
          data: errorData,
          message: error.message
        });

        if (status === 401) {
          console.error('🔐 Session expirée ou token invalide');
          setError('Session expirée. Veuillez vous reconnecter.');
          localStorage.removeItem('authToken');
          localStorage.removeItem('token');
          localStorage.removeItem('userData');

          // Rediriger vers la page de connexion après 2 secondes
          setTimeout(() => {
            window.location.href = '/login';
          }, 2000);
        } else if (status === 403) {
          setError('Accès refusé. Vous n\'avez pas les permissions nécessaires.');
        } else if (status === 404) {
          setError('Ressource non trouvée.');
        } else if (status === 500) {
          setError('Erreur serveur. Veuillez réessayer plus tard.');
        } else if (error.code === 'ECONNABORTED') {
          setError('Délai d\'attente dépassé. Veuillez vérifier votre connexion.');
        } else if (!error.response) {
          setError('Erreur réseau. Veuillez vérifier votre connexion internet.');
        } else {
          setError(errorData?.message || error.message || 'Une erreur est survenue');
        }

        return Promise.reject(error);
      }
    );

    return instance;
  }, [getToken]);

  // Récupérer les messages d'une conversation
  const fetchMessages = useCallback(async (conversationId) => {
    if (!conversationId) {
      console.error('❌ fetchMessages: conversationId manquant');
      setError('ID de conversation manquant');
      return [];
    }

    try {
      console.log(`📥 fetchMessages appelé pour conversation: ${conversationId}`);
      setLoading(true);
      setError(null);

      const axiosInstance = createAxiosInstance();
      const response = await axiosInstance.get(`/messages/conversations/${conversationId}/messages`);

      console.log(`📨 Réponse fetchMessages pour ${conversationId}:`, response.data);

      if (response.data.success) {
        const messagesData = response.data.messages || [];
        const conversationData = response.data.conversation;

        setMessages(messagesData);
        setCurrentConversation(conversationData);

        // Mettre à jour la conversation dans la liste
        setConversations(prev => prev.map(conv => 
          conv.id === conversationId 
            ? { ...conv, last_message: conversationData?.last_message, unread_count: 0 }
            : conv
        ));

        return messagesData;
      } else {
        throw new Error(response.data.message || 'Erreur lors du chargement des messages');
      }
    } catch (err) {
      console.error(`❌ Erreur fetchMessages pour ${conversationId}:`, err);
      setError(err.response?.data?.message || err.message || 'Erreur lors du chargement des messages');
      throw err;
    } finally {
      setLoading(false);
    }
  }, [createAxiosInstance]);

  // Récupérer toutes les conversations
  const fetchConversations = useCallback(async (forceRefresh = false) => {
    try {
      console.log('📥 fetchConversations appelé');
      if (forceRefresh || conversations.length === 0) {
        setLoading(true);
      }
      setError(null);

      const axiosInstance = createAxiosInstance();
      const response = await axiosInstance.get('/messages/conversations');

      console.log('💬 Réponse fetchConversations:', {
        success: response.data.success,
        count: response.data.conversations?.length || 0,
        data: response.data
      });

      if (response.data.success) {
        const conversationsData = response.data.conversations || [];
        setConversations(conversationsData);

        // Si une conversation est actuellement sélectionnée, la mettre à jour
        if (currentConversation) {
          const updatedConv = conversationsData.find(c => c.id === currentConversation.id);
          if (updatedConv) {
            setCurrentConversation(updatedConv);
          }
        }

        return conversationsData;
      } else {
        throw new Error(response.data.message || 'Erreur lors du chargement des conversations');
      }
    } catch (err) {
      console.error('❌ Erreur fetchConversations:', err);
      setError(err.response?.data?.message || err.message || 'Erreur lors du chargement des conversations');

      // Si c'est une erreur 401, on retourne un tableau vide
      if (err.response?.status === 401) {
        setConversations([]);
        return [];
      }

      throw err;
    } finally {
      setLoading(false);
    }
  }, [createAxiosInstance, conversations.length, currentConversation]);

  // Créer ou récupérer une conversation
  const getOrCreateConversation = useCallback(async (adminId) => {
    if (!adminId) {
      console.error('❌ getOrCreateConversation: adminId manquant');
      setError('ID d\'admin manquant');
      return null;
    }

    try {
      console.log(`➕ getOrCreateConversation appelé pour admin: ${adminId}`);
      setLoading(true);
      setError(null);

      // Vérifier d'abord les conversations existantes
      if (conversations.length > 0) {
        const existing = conversations.find(c => 
          (c.admin_id === adminId || c.adminId === adminId) && 
          c.status !== 'closed' && 
          c.status !== 'archived'
        );

        if (existing) {
          console.log(`✅ Conversation existante trouvée: ${existing.id}`);
          await fetchMessages(existing.id);
          return existing;
        }
      }

      // Créer une nouvelle conversation
      const axiosInstance = createAxiosInstance();
      const response = await axiosInstance.post('/messages/conversations', {
        admin_id: adminId
      });

      console.log('📝 Réponse création conversation:', response.data);

      if (response.data.success) {
        const newConv = response.data.conversation;

        // Ajouter la nouvelle conversation
        setConversations(prev => [newConv, ...prev]);
        setCurrentConversation(newConv);
        setMessages([]); // Réinitialiser les messages

        return newConv;
      } else {
        throw new Error(response.data.message || 'Erreur lors de la création de la conversation');
      }
    } catch (err) {
      console.error('❌ Erreur getOrCreateConversation:', err);
      setError(err.response?.data?.message || err.message || 'Erreur lors de la création de la conversation');
      throw err;
    } finally {
      setLoading(false);
    }
  }, [conversations, createAxiosInstance, fetchMessages]);

  // Envoyer un message - CORRECTION
  const sendMessage = useCallback(async (conversationId, content) => {
    if (!conversationId || !content || content.trim() === '') {
      console.error('❌ sendMessage: paramètres manquants ou invalides');
      setError('Le message ne peut pas être vide');
      return null;
    }

    try {
      console.log('📤 sendMessage appelé:', { conversationId, content });
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.post('/messages', {
        conversation_id: conversationId,
        content: content.trim()
      });

      console.log('✅ Réponse sendMessage:', response.data);

      if (response.data.success) {
        const newMessage = response.data.data || response.data.message;

        if (newMessage) {
          // Ajouter le nouveau message à la liste
          setMessages(prev => [...prev, newMessage]);

          // Mettre à jour la conversation dans la liste
          setConversations(prev => prev.map(conv => {
            if (conv.id === conversationId) {
              return {
                ...conv,
                last_message: content.trim(),
                last_message_time: new Date().toISOString(),
                updated_at: new Date().toISOString(),
                unread_count: 0 // Remettre à 0 car l'utilisateur actuel a envoyé le message
              };
            }
            return conv;
          }));

          // Mettre à jour la conversation actuelle
          if (currentConversation && currentConversation.id === conversationId) {
            setCurrentConversation(prev => ({
              ...prev,
              last_message: content.trim(),
              last_message_time: new Date().toISOString(),
              updated_at: new Date().toISOString()
            }));
          }
        }

        return newMessage;
      } else {
        throw new Error(response.data.message || 'Erreur lors de l\'envoi du message');
      }
    } catch (err) {
      console.error('❌ Erreur sendMessage:', err);
      console.error('Détails erreur:', {
        status: err.response?.status,
        data: err.response?.data,
        message: err.message
      });

      const errorMsg = err.response?.data?.message || 
                      err.response?.data?.error || 
                      err.message || 
                      'Erreur lors de l\'envoi du message';

      setError(errorMsg);
      throw new Error(errorMsg);
    }
  }, [createAxiosInstance, currentConversation]);

  // Récupérer les admins
  const fetchAdmins = useCallback(async () => {
    try {
      console.log('👥 fetchAdmins appelé');
      const axiosInstance = createAxiosInstance();
      const response = await axiosInstance.get('/messages/admins');

      console.log('✅ Réponse fetchAdmins:', {
        success: response.data.success,
        count: response.data.admins?.length || 0
      });

      return response.data.success ? (response.data.admins || []) : [];
    } catch (err) {
      console.error('❌ Erreur fetchAdmins:', err);
      setError(err.response?.data?.message || 'Erreur lors de la récupération des admins');
      return [];
    }
  }, [createAxiosInstance]);

  // Récupérer les admins disponibles
  const fetchAvailableAdmins = useCallback(async () => {
    try {
      console.log('👥 fetchAvailableAdmins appelé');
      const axiosInstance = createAxiosInstance();
      const response = await axiosInstance.get('/messages/admins/available');

      console.log('✅ Réponse fetchAvailableAdmins:', {
        success: response.data.success,
        count: response.data.admins?.length || 0
      });

      return response.data.success ? (response.data.admins || []) : [];
    } catch (err) {
      console.error('❌ Erreur fetchAvailableAdmins:', err);
      setError(err.response?.data?.message || 'Erreur lors de la récupération des admins disponibles');
      return [];
    }
  }, [createAxiosInstance]);

  // Marquer les messages comme lus
  const markMessagesAsRead = useCallback(async (conversationId) => {
    if (!conversationId) return;

    try {
      console.log(`👁️ markMessagesAsRead pour conversation: ${conversationId}`);
      const axiosInstance = createAxiosInstance();

      await axiosInstance.post('/messages/read', {
        conversation_id: conversationId
      });

      // Mettre à jour localement
      setConversations(prev => prev.map(conv => {
        if (conv.id === conversationId) {
          return { ...conv, unread_count: 0 };
        }
        return conv;
      }));

      console.log(`✅ Messages marqués comme lus pour ${conversationId}`);
    } catch (err) {
      console.error('❌ Erreur markMessagesAsRead:', err);
      // Ne pas afficher d'erreur pour cette opération non critique
    }
  }, [createAxiosInstance]);

  // Rafraîchir périodiquement les conversations
  useEffect(() => {
    const token = getToken();
    if (!token) return;

    fetchConversations();

    // Rafraîchir toutes les 30 secondes
    const interval = setInterval(() => {
      fetchConversations(false); // Rafraîchissement silencieux
    }, 30000);

    return () => clearInterval(interval);
  }, [getToken, fetchConversations]);

  return {
    // État
    conversations,
    messages,
    currentConversation,
    loading,
    error,

    // Setters
    setCurrentConversation,
    setError,
    setMessages,

    // Actions
    fetchConversations,
    getOrCreateConversation,
    fetchMessages,
    sendMessage,
    fetchAdmins,
    fetchAvailableAdmins,
    markMessagesAsRead,

    // Utilitaires
    refreshConversations: () => fetchConversations(true)
  };
};

export default useMessages;
